// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { AreaChart } from "@/registry/erbium/charts/area-chart";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { AreaChart } from \"@/registry/erbium/charts/area-chart\";\nimport { devices, shortMonth, visitors } from \"../examples/data\";\n\nconst Example = (args: {\n  axis: boolean;\n  curve: \"smooth\" | \"linear\" | \"step\";\n  fill: \"gradient\" | \"solid\";\n  grid: boolean;\n  legend: boolean;\n  stacked: boolean;\n  tooltip: boolean;\n}) => (\n  <div className=\"w-2xl max-w-full p-4\">\n    <AreaChart\n      ariaLabel=\"Visitors by month and device\"\n      data={visitors}\n      index=\"month\"\n      indexFormat={shortMonth}\n      series={devices}\n      initialWidth={640}\n      {...args}\n    />\n  </div>\n);\n\nexport default Example;\n";

import StackedExample from "./variants/stacked";

const StackedSource = "import { AreaChart } from \"@/registry/erbium/charts/area-chart\";\nimport { devices, shortMonth, visitors } from \"../examples/data\";\n\nconst Example = () => (\n  <div className=\"w-2xl max-w-full p-4\">\n    <AreaChart\n      ariaLabel=\"Visitors by month, stacked by device\"\n      data={visitors}\n      index=\"month\"\n      indexFormat={shortMonth}\n      series={devices}\n      stacked\n      initialWidth={640}\n    />\n  </div>\n);\n\nexport default Example;\n";

const meta = {
  component: AreaChart,
  parameters: {
    docs: {
      description: {
        component: "## Usage\n\nArea charts take the same props as the [Line Chart](/docs/charts/line-chart), plus `stacked` and `fill`. The default `gradient` fill fades each series toward the baseline in its own color.\n\n```tsx\nimport { AreaChart } from \"@/registry/erbium/charts/area-chart\";\n\n<AreaChart ariaLabel=\"Visitors by month\" data={visitors} index=\"month\" series={devices} stacked />;\n```\n\nUnstacked areas overlap, so keep them to two or three series. When exact values matter more than shape, use a line chart or a table.",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof AreaChart>;

export default { ...meta, title: "Charts/Area Chart",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  axis: boolean;
  curve: "smooth" | "linear" | "step";
  fill: "gradient" | "solid";
  grid: boolean;
  legend: boolean;
  stacked: boolean;
  tooltip: boolean;
}> = {
  argTypes: {
    axis: { control: "boolean" },
    curve: { control: "inline-radio", options: ["smooth", "linear", "step"] },
    fill: { control: "inline-radio", options: ["gradient", "solid"] },
    grid: { control: "boolean" },
    legend: { control: "boolean" },
    stacked: { control: "boolean" },
    tooltip: { control: "boolean" },
  },
  args: {
    axis: true,
    curve: "smooth",
    fill: "gradient",
    grid: true,
    legend: true,
    stacked: false,
    tooltip: true,
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Stacked: Story = {
  parameters: {
    docs: {
      description: { story: "Stacked areas keep the total on the top edge and give each series a layer of its own thickness." },
      source: { code: StackedSource },
    },
  },
  render: StackedExample,
};

import type { ChartValue } from "@tanstack/charts";
import { formatChartIndex } from "@/registry/erbium/charts/chart";

export const visitors = [
  { desktop: 186, mobile: 80, month: "January" },
  { desktop: 305, mobile: 200, month: "February" },
  { desktop: 237, mobile: 120, month: "March" },
  { desktop: 73, mobile: 190, month: "April" },
  { desktop: 209, mobile: 130, month: "May" },
  { desktop: 214, mobile: 140, month: "June" },
];

export const devices = [
  { key: "desktop", label: "Desktop" },
  { key: "mobile", label: "Mobile" },
] as const;

export const shortMonth = (value: ChartValue) => formatChartIndex(value).slice(0, 3);

import { AreaChart } from "@/registry/erbium/charts/area-chart";
import { devices, shortMonth, visitors } from "../examples/data";

const Example = (args: {
  axis: boolean;
  curve: "smooth" | "linear" | "step";
  fill: "gradient" | "solid";
  grid: boolean;
  legend: boolean;
  stacked: boolean;
  tooltip: boolean;
}) => (
  <div className="w-2xl max-w-full p-4">
    <AreaChart
      ariaLabel="Visitors by month and device"
      data={visitors}
      index="month"
      indexFormat={shortMonth}
      series={devices}
      initialWidth={640}
      {...args}
    />
  </div>
);

export default Example;

import { AreaChart } from "@/registry/erbium/charts/area-chart";
import { devices, shortMonth, visitors } from "../examples/data";

const Example = () => (
  <div className="w-2xl max-w-full p-4">
    <AreaChart
      ariaLabel="Visitors by month, stacked by device"
      data={visitors}
      index="month"
      indexFormat={shortMonth}
      series={devices}
      stacked
      initialWidth={640}
    />
  </div>
);

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </SkeletonProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);
